mapper.update:
UPDATE the_full_order.tb_supplier_site SET provider_listed_yn='N'
 WHERE supplier_id=#{supplier_id} AND provider_listed_yn='Y'
   AND external_site_code NOT IN #{code}

mapper.select:
SELECT account_id FROM the_full_order.tb_supplier_account_site
 WHERE supplier_id=#{supplier_id} AND external_site_code=#{external_site_code} AND active_yn='Y' AND account_id<>#{account_id}
 ORDER BY account_id

mapper.update:
UPDATE the_full_order.tb_supplier_account_site ss
  JOIN the_full_order.tb_supplier_site m ON m.supplier_id=ss.supplier_id AND m.external_site_code=ss.external_site_code
   SET ss.active_yn='Y',ss.external_site_name=m.external_site_name,ss.representative_site_code=m.representative_site_code,
       ss.center_code=m.center_code,ss.price_context_code=COALESCE(m.price_context_code,ss.price_context_code),
       ss.provider_attributes=m.provider_attributes,ss.last_synced_at=NOW(),ss.user_id=#{user_id}
 WHERE ss.account_id=#{account_id} AND ss.supplier_id=#{supplier_id} AND ss.external_site_code=#{external_site_code}
